const id = Number($json.id);
if (!Number.isSafeInteger(id) || id <= 0) throw new Error('INVALID_REPORT_ID');
return { json: { report_id: id } };

const client = $json;
const report = $('Read Saved Report').item.json;
const job = $('Claim Notification').item.json;
if (Number(client.id) !== Number(report.client_id) || Number(job.client_id) !== Number(client.id) || Number(job.report_id) !== Number(report.id)) throw new Error('NOTIFICATION_SCOPE_MISMATCH');
const now = Date.now();
const trial = client.subscription_status === 'trial' && Date.parse(client.trial_ends_at || '') > now;
const paid = client.subscription_status === 'active' && (!client.current_period_end || Date.parse(client.current_period_end) > now);
const email = typeof client.email === 'string' ? client.email.trim() : '';
if ((!trial && !paid) || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return { json: { skip: true, error_code: !trial && !paid ? 'SUBSCRIPTION_INACTIVE' : 'CLIENT_EMAIL_MISSING' } };
// Use the saved report's FK relations, never names supplied by the caller or AI.
const branch = report.branch;
const platform = report.platform;
if ((branch && (Number(branch.id) !== Number(report.branch_id) || Number(branch.client_id) !== Number(client.id))) ||
    (platform && (Number(platform.id) !== Number(report.platform_id) || Number(platform.client_id) !== Number(client.id)))) throw new Error('NOTIFICATION_LABEL_SCOPE_MISMATCH');
const clean = (value, max = 2000) => String(value ?? '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f\u202a-\u202e\u2066-\u2069]/g, '').trim().slice(0, max);
const escape = value => String(value).replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const excerpt = (value, max) => {
  const text = clean(value);
  return escape(text.length > max ? text.slice(0, max).trimEnd() + '…' : text);
};
const name = clean(client.name, 120) || 'عميل IntelEye';
const branchName = clean(branch?.name, 120) || 'الفرع غير محدد';
const platformNames = { google_maps: 'خرائط Google', x: 'X', tiktok: 'TikTok', instagram: 'Instagram' };
const platformName = Object.hasOwn(platformNames, platform?.platform_name) ? platformNames[platform.platform_name] : 'المنصة غير محددة';
// Display the recorded calendar day, without inventing a timezone for old timestamps.
const formatDay = value => {
  const day = clean(value, 40).match(/^(\d{4}-\d{2}-\d{2})(?:T|$)/)?.[1];
  const date = day ? new Date(day + 'T12:00:00Z') : null;
  if (!date || !Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== day) return 'غير متاح';
  return new Intl.DateTimeFormat('ar-SA-u-ca-gregory-nu-arab', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(date);
};
const period = `${formatDay(report.period_start)} إلى ${formatDay(report.period_end)}`;
const includeUrgent = paid && ['pro', 'enterprise'].includes(client.plan);
const savedCases = Array.isArray(report.stats?.reputation_urgent_cases) ? report.stats.reputation_urgent_cases : [];
const cases = includeUrgent ? savedCases.filter(row => row && Number(row.client_id) === Number(client.id) && Number(row.platform_id) === Number(report.platform_id) && (row.branch_id ?? null) === (report.branch_id ?? null) && ['high', 'critical'].includes(row.severity) && (row.sentiment === 'negative' || row.is_complaint === true)) : [];
// Keep the email readable and below Gmail's clipping threshold; full details stay in the report.
const visibleCases = cases.slice(0, 5);
const reportUrl = 'https://www.inteleye-sa.com/dashboard/reports';
const logoUrl = 'https://www.inteleye-sa.com/logo.png';
const label = 'font-size:13px;line-height:1.8;color:#73758a;';
const paragraph = 'margin:0;font-size:15px;line-height:1.9;color:#34384f;overflow-wrap:anywhere;word-break:break-word;';
const button = text => `<table role="presentation" cellpadding="0" cellspacing="0" style="margin:20px auto;border-collapse:separate;"><tr><td bgcolor="#374375" style="background-color:#374375;border-radius:10px;text-align:center;"><a href="${reportUrl}" style="display:inline-block;padding:14px 24px;border:1px solid #374375;border-radius:10px;font-family:Tahoma,Arial,sans-serif;font-size:15px;font-weight:bold;color:#ffffff;text-decoration:none;">${text}</a></td></tr></table>`;
const cards = visibleCases.map((row, index) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;table-layout:fixed;margin-top:16px;border:1px solid #e7e7ee;border-radius:12px;border-collapse:separate;background-color:#ffffff;"><tr><td style="padding:20px;text-align:right;">
<p style="margin:0 0 8px;font-size:16px;font-weight:bold;color:#895159;">${index + 1}. تعليق مصنّف ${row.severity === 'critical' ? 'حرج الخطورة' : 'عالي الخطورة'}</p>
<p style="margin:0 0 12px;${label}"><span dir="auto">${escape(branchName)}</span> &nbsp;·&nbsp; <span dir="auto">${escape(platformName)}</span> &nbsp;·&nbsp; ${formatDay(row.published_at)}</p>
<p style="margin:0 0 6px;${label}">من تعليق العميل:</p>
<p dir="auto" style="${paragraph}padding:12px;background-color:#f8f7f3;border-right:3px solid #babde2;border-radius:6px;white-space:pre-line;">${excerpt(row.feedback_text, 420) || 'نص التعليق غير متاح؛ راجع التقرير.'}</p>
<p style="margin:14px 0 4px;font-size:13px;font-weight:bold;color:#374375;">سبب التصنيف المقترح:</p>
<p dir="auto" style="${paragraph}">${excerpt(row.reason, 300) || 'راجع تفاصيل الحالة داخل التقرير.'}</p>
<p style="margin:14px 0 4px;font-size:13px;font-weight:bold;color:#374375;">رد مقترح — للمراجعة قبل النشر:</p>
<p dir="auto" style="${paragraph}white-space:pre-line;">${excerpt(row.suggested_reply, 500) || 'لا يوجد رد مقترح محفوظ لهذه الحالة.'}</p>
</td></tr></table>`).join('');
const urgentSection = cases.length ? `<tr><td style="padding:0 24px 24px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;border-collapse:separate;background-color:#faf1f1;border-radius:10px;"><tr><td style="padding:16px;">
<h2 style="margin:0 0 6px;font-size:18px;line-height:1.7;color:#895159;">حالات عالية الخطورة تستحق مراجعتكم</h2>
<p style="${paragraph}">عدد الحالات المصنّفة عالية أو حرجة الخطورة في هذا التقرير: <strong>${cases.length}</strong>. يُرجى مراجعة الوقائع قبل اتخاذ إجراء.</p>
</td></tr></table>${cards}
${cases.length > visibleCases.length ? `<p style="margin:16px 0 0;${paragraph}">نعرض هنا ${visibleCases.length} حالات من أصل ${cases.length}. بقية الحالات والنصوص الكاملة متاحة داخل التقرير.</p>` : `<p style="margin:16px 0 0;${label}">قد تُختصر النصوص في البريد؛ التفاصيل الكاملة متاحة داخل التقرير.</p>`}
${button('مشاهدة التقرير ومتابعة الحالات')}</td></tr>` : '';
const message = `<!doctype html>
<html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تقريرك الأسبوعي جاهز — IntelEye</title></head>
<body dir="rtl" style="margin:0;padding:0;width:100%;background-color:#f8f7f3;font-family:Tahoma,Arial,sans-serif;color:#34384f;-webkit-text-size-adjust:100%;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" bgcolor="#f8f7f3" style="width:100%;table-layout:fixed;background-color:#f8f7f3;"><tr><td align="center" style="padding:24px 12px;">
<!--[if mso]><table role="presentation" width="600" cellpadding="0" cellspacing="0"><tr><td><![endif]-->
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" dir="rtl" style="width:100%;max-width:600px;table-layout:fixed;background-color:#ffffff;border:1px solid #e7e7ee;border-radius:16px;border-collapse:separate;overflow-wrap:anywhere;word-break:break-word;text-align:right;">
<tr><td align="center" style="padding:28px 24px 18px;border-bottom:1px solid #eeeef4;">
<img src="${logoUrl}" width="64" height="68" alt="شعار IntelEye" style="display:block;width:64px;height:68px;margin:0 auto 8px;border:0;">
<p dir="ltr" style="margin:0;font-family:Tahoma,Arial,sans-serif;font-size:22px;font-weight:bold;letter-spacing:1px;color:#374375;">IntelEye</p>
<p style="margin:6px 0 0;font-size:13px;color:#73758a;">رؤية أوضح لآراء عملائك</p>
</td></tr>
<tr><td style="padding:24px;">
<h1 style="margin:0 0 12px;font-size:25px;line-height:1.6;color:#374375;">تقريرك الأسبوعي جاهز</h1>
<p style="${paragraph}">مرحبًا بفريق <strong dir="auto">${escape(name)}</strong>،<br>اكتمل تحليل آراء عملائكم. يمكنكم الآن الاطلاع على التقرير ومتابعة أبرز الملاحظات.</p>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="width:100%;table-layout:fixed;margin-top:20px;background-color:#f8f7f3;border-radius:10px;"><tr><td style="padding:16px;">
<p style="margin:0 0 6px;${paragraph}"><strong>المنشأة:</strong> <span dir="auto">${escape(name)}</span></p>
<p style="margin:0 0 6px;${paragraph}"><strong>الفرع:</strong> <span dir="auto">${escape(branchName)}</span></p>
<p style="margin:0 0 6px;${paragraph}"><strong>المنصة:</strong> <span dir="auto">${escape(platformName)}</span></p>
<p style="${paragraph}"><strong>فترة التقرير:</strong> ${escape(period)}</p>
</td></tr></table>
${button('عرض التقرير الكامل')}
</td></tr>
${urgentSection}
<tr><td style="padding:20px 24px;background-color:#f5f5fa;border-top:1px solid #e7e7ee;border-radius:0 0 16px 16px;">
<p style="margin:0;font-size:12px;line-height:1.9;color:#65677b;">${includeUrgent ? 'التصنيفات والردود مقترحة بمساعدة الذكاء الاصطناعي، ولا تثبت صحة الادعاءات أو أسبابها. يُرجى مراجعة الوقائع والصياغة قبل اتخاذ إجراء أو نشر رد. لا تُنشر الردود تلقائيًا.' : 'هذا التقرير تحليل مساعد لآراء العملاء؛ يُرجى مراجعة التفاصيل قبل اتخاذ إجراء.'}</p>
<p style="margin:12px 0 0;font-size:12px;line-height:1.8;color:#73758a;">رقم التقرير: ${escape(clean(report.id, 24))} &nbsp;·&nbsp; IntelEye</p>
<p style="margin:8px 0 0;font-size:12px;line-height:1.8;"><a href="${reportUrl}" style="color:#374375;text-decoration:underline;">فتح صفحة التقارير في IntelEye</a></p>
</td></tr></table>
<!--[if mso]></td></tr></table><![endif]-->
</td></tr></table></body></html>`;
const subject = `IntelEye | تقريرك الأسبوعي جاهز — ${name} | ${branchName} | ${platformName}`.replace(/\s+/g, ' ').slice(0, 240);
return { json: { skip: false, recipient_email: email, subject, message, urgent_count: cases.length, displayed_urgent_count: visibleCases.length } };

const status = Number($json.error?.httpCode ?? $json.error?.statusCode ?? $json.httpCode ?? $json.statusCode);
const definite = [400, 401, 403, 404, 429].includes(status);
return { json: { status: definite ? 'failed' : 'unknown', error_code: definite ? `GMAIL_REJECTED_${status}` : 'GMAIL_RESULT_UNKNOWN' } };
